theory = (
 H("A", "Deciding and influencing", "Quyết định và gây ảnh hưởng")
 + P("Four short texts about decisions at work and in life.", "Bốn đoạn ngắn về chuyện ra quyết định trong công việc và cuộc sống.")
 + T([
    ("<b>decide on</b> / <b>mull over</b> / <b>tie</b> sb <b>down</b> (Unit 10)", "Someone must choose about a job offer; they have thought about it for a long time but don’t want to lose their freedom to something they may regret.", "Một người phải quyết về lời mời làm việc; đã nghĩ rất lâu nhưng không muốn bị ràng buộc vào điều có thể hối tiếc."),
    ("<b>toy with</b> / <b>size up</b>", "Another person has been considering a big life change, not very seriously, and now needs to examine the situation carefully before deciding.", "Một người khác từng tính chuyện đổi đời nhưng chưa nghiêm túc, giờ cần đánh giá kỹ tình hình trước khi quyết."),
    ("<b>push through</b> / <b>single out</b>", "Changes will be made official at work; the listener has been chosen from the group for praise.", "Những thay đổi sắp được thông qua ở công ty; người nghe vừa được chọn ra để khen ngợi."),
    ("<b>play</b> sb <b>off against</b> sb / <b>do</b> sb <b>out of</b>", "Managers may be making two rivals compete for their own advantage, and the rival might unfairly stop the listener getting the promotion (informal).", "Ban quản lý có thể đang cố ý cho hai đối thủ tranh nhau để hưởng lợi, và đối thủ có thể giành mất suất thăng chức một cách bất công (thân mật)."),
    ("<b>reason with</b> / <b>play on</b> / <b>work out</b>", "A colleague is hard to persuade with good arguments; don’t let her use your good nature unfairly; try to make a plan to solve things together.", "Một đồng nghiệp rất khó thuyết phục bằng lý lẽ; đừng để cô ta lợi dụng tính tốt của bạn; hãy cố cùng tìm cách giải quyết."),
 ])
 + H("B", "Second speakers paraphrasing", "Người thứ hai diễn đạt lại")
 + T([
    ("<b>tend towards</b>", "Ahmed is not sure but is likely to choose Moscow over Berlin.", "Ahmed chưa chắc nhưng nghiêng về Moscow hơn Berlin."),
    ("<b>toss for</b>", "Two friends decide who gets a spare ticket by throwing a coin (heads or tails).", "Hai người quyết ai lấy vé dư bằng cách tung đồng xu (sấp hay ngửa)."),
    ("<b>arrive at</b>", "Ryan has at last made his decision about a job in Madrid.", "Ryan cuối cùng đã quyết về công việc ở Madrid."),
    ("<b>come round to</b>", "Lucy now agrees with Stan’s idea after being against it (see Unit 23).", "Lucy giờ đã đồng ý với ý của Stan sau khi từng phản đối (xem bài 23)."),
    ("<b>drum up</b>", "They need to increase support for their campaign.", "Họ cần kêu gọi thêm ủng hộ cho chiến dịch."),
 ])
 + NOTE("<b>Tip</b> (from the book): <b>do</b> forms a group of informal phrasal verbs – cheating someone of something (<b>do</b> sb <b>out of</b>), killing (<b>do in</b>), decorating a room (<b>do out</b>), making yourself look nicer (<b>do yourself up</b>) and managing without something (<b>do without</b>). Record groups like this together. <b>29.2</b>: someone <b>tending towards</b> something has not decided yet; <b>drum up</b> may come from army drummers encouraging soldiers.",
        "<b>Mẹo</b> (của sách): <b>do</b> tạo thành một nhóm phrasal verb thân mật – <b>do</b> sb <b>out of</b> sth, <b>do in</b> sb (giết), <b>do out</b> sth (trang trí), <b>do yourself up</b> (làm đẹp), <b>do without</b> (xoay xở khi thiếu). Hãy ghi những nhóm như vậy cạnh nhau. <b>29.2</b>: ai <b>tending towards</b> điều gì là chưa quyết hẳn; <b>drum up</b> có thể bắt nguồn từ người đánh trống trong quân đội cổ vũ binh lính.")
)
